with flagged as (select *, case when lag(txn_time) over (partition by account_id order by txn_time, id) is null or txn_time > lag(txn_time) over (partition by account_id order by txn_time, id) + interval '90' day then 1 else 0 end as is_new_session from transactions), sessions_transactions as (select *, sum(is_new_session) over (partition by account_id order by txn_time, id rows between unbounded preceding and current row) as island_id from flagged) select id, txn_type, amount, merchant, case when txn_type rlike '^(REFUND|DEBIT)$' then 'GROUP_A' when txn_type rlike '^(CREDIT|FEE)$' then 'OTHER_ZONE' else 'PRIORITY' end as txn_type_zone from sessions_transactions order by merchant nulls last
